import React from 'react';
import { Box, Typography, IconButton, Stack, Paper } from '@mui/material';
import {
  Savings,
  AccountBalanceWallet,
  Payment,
  History,
  AddCircleOutline,
  MoreHoriz,
  Person,
  PersonOutline,
  ContactsOutlined,
  SettingsOutlined,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';

const menuItems = [
  { label: 'เงินดาวน์', icon: <Savings /> },
  { label: 'สินเชื่อ', icon: <AccountBalanceWallet /> },
  { label: 'ชำระเงิน', icon: <Payment /> },
  { label: 'ประวัติ', icon: <History /> },
  { label: 'สินเชื่อใหม่', icon: <AddCircleOutline /> },
  { label: 'ตั้งค่า', icon: <SettingsOutlined /> },
  { label: 'ติดต่อ', icon: <ContactsOutlined /> },
  { label: 'ข้อมูลส่วนตัว', icon: <PersonOutline /> },
];

const HomeMenu = () => {

  const navigate = useNavigate();
  return (
    <Box p={3} >
      <Stack direction="row" flexWrap="wrap" spacing={2} useFlexGap justifyContent={'center'} >
        {menuItems.map((item, index) => (
          <Paper
            key={index}
            elevation={1}
            sx={{
              width: '120px',
              height: '120px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              background: 'linear-gradient(135deg, #2f9275ff 0%, #2f7c69ff 50%, #208372ff 100%)',
              '&:hover': {
                background: 'linear-gradient(135deg, #266955ff 0%, #125f4cff 50%, #0e8d78ff 100%)',
                cursor: 'pointer',
              },
            }}
          >
            <IconButton color='info'>{item.icon}</IconButton>
            <Typography variant="body2" mt={1} color='info'>
              {item.label}
            </Typography>
          </Paper>
        ))}
      </Stack>
    </Box>
  );
};

export default HomeMenu;
